    pub fn payload(mut self, value: impl Into<String>) -> Self {
        self.payload = Some(value.into());
        self
    }

    /// Sets [`payload`](Self::payload) if `value` is `Some`.
    pub fn maybe_payload(mut self, value: Option<String>) -> Self {
        self.payload = value;
        self
    }

